        cin >> a[i];
    }
    int count = 0;
    for (int i = 0; i < 8; ++i) {
        for (int j = i + 1; j < 8; ++j) {
            for (int k = 0; k < 5; ++k) {
                if (a[i].length() > k && a[j].length() > k
                    && a[i][k] == a[j][k]) {
                    ++count;
                }
            }
        }
    }
    cout << count;
}

